SELECT CASE WHEN d.budget >= 3754000 THEN 'high' WHEN d.budget >= 1271000 THEN 'mid' ELSE 'low' END budget_bucket, d.dept_name, ROUND(STDDEV(e.salary), 2) stddev_salary FROM employees e JOIN departments d ON e.dept_id = d.id WHERE d.location = 'Tokyo' GROUP BY CASE WHEN d.budget >= 3754000 THEN 'high' WHEN d.budget >= 1271000 THEN 'mid' ELSE 'low' END, d.dept_name HAVING ROUND(STDDEV(e.salary), 2) > 39;
